namespace sv_5f79c5c52a7e4611a5961210d0298243.Components;

public enum ScreenSize
{
    Mobile,
    Tablet,
    Desktop
}

@implements IAsyncDisposable

<CascadingValue Value="currentSize">
    @ChildContent
</CascadingValue>

@code {
    [Parameter]
    public RenderFragment? ChildContent { get; set; }

    private ScreenSize currentSize = ScreenSize.Desktop;
    private IJSObjectReference? module;
    private DotNetObjectReference<ScreenSizeProvider>? objRef;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            objRef = DotNetObjectReference.Create(this);
            module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./_content/sv-5f79c5c52a7e4611a5961210d0298243/screenSize.js");
            await module.InvokeVoidAsync("listenToResize", objRef);
        }
    }

    [JSInvokable]
    public void OnViewportWidthChanged(int width)
    {
        var newSize = width switch
        {
            < 768 => ScreenSize.Mobile,
            < 1024 => ScreenSize.Tablet,
            _ => ScreenSize.Desktop
        };

        if (newSize != currentSize)
        {
            currentSize = newSize;
            StateHasChanged();
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (module is not null)
        {
            try
            {
                await module.InvokeVoidAsync("stopListening");
                await module.DisposeAsync();
            }
            catch (JSDisconnectedException) { }
        }

        objRef?.Dispose();
    }
}

let handler = null;

export function listenToResize(dotnetRef) {
    dotnetRef.invokeMethodAsync("OnViewportWidthChanged", window.innerWidth);

    handler = () => {
        dotnetRef.invokeMethodAsync("OnViewportWidthChanged", window.innerWidth);
    };

    window.addEventListener("resize", handler);
}

export function stopListening() {
    if (handler) {
        window.removeEventListener("resize", handler);
        handler = null;
    }
}

